 for(let [channel,value]of sources){try{let result=inferFirstTiming(data.map(r=>[r.global_time_s,r.quality_review_status==='exclude'?NaN:value(r)]),plan);found.push({...result,channel})}catch(e){errors.push(e.message)}}
 if(!found.length)throw Error(errors[0]||'지속되는 색 변화가 명확하지 않아 주입 시작을 추정하지 못했습니다.');
