 let chosen=groups[0].members,first=med(chosen.map(r=>r.first)),representative=chosen.slice().sort((a,b)=>b.recovery_checks-a.recovery_checks||(a.agreement_spread_s||0)-(b.agreement_spread_s||0))[0],offsets=[0];for(let i=1;i<plan.length;i++)offsets.push(offsets.at(-1)+plan[i-1].on+plan[i-1].air);
